#include "equilibrium/gibbs_minimizer.hpp"
#include "equilibrium_support.hpp"
#include "properties_support.hpp"
#include <fstream>
#include <sstream>
#include <iomanip>
#include <iostream>
#include "qualification_clock.hpp"
using namespace epcsaft;using namespace epcsaft::equilibrium;
int main(int argc,char**argv){QualificationClock identity;HelmholtzModel m(properties_support::neutral_binary());std::ifstream in(argv[1]);std::ofstream events(argv[2]);events<<std::setprecision(20)<<"set,row,arm,event,T,value1,value2,value3,reason\n";std::cout<<std::setprecision(20)<<"set,row,arm,complete,success,T,P,rhoL,rhoV,x0,x1,x2,x3,bits,corrections,evaluations,iterations,hessians,radiusL,radiusV,pressure_radius,cause,activations,decisions,decision_radius,raw_residual,classified_residual,requested_tolerance,requested_row_tolerance\n";std::string line;while(std::getline(in,line)){std::istringstream s(line);std::string set,arm;int row,components;double t,p;std::vector<double>x(4),rho(2),y(10);s>>set>>row>>arm>>components>>t>>p;for(auto&v:x)s>>v;for(auto&v:rho)s>>v;for(auto&v:y)s>>v;
for(int complete=0;complete<1;complete++){auto problem=equilibrium_support::bubble_at(t);const double P0[]={1e5,1e6,2.02606e6,3e6,5e6,6.75e6,7e6};problem.pressure=FreeValue::variable(set=="840"?(row==2?7e6:6.75e6):P0[row%7]);EquilibriumResult r; core::Capture capture(true);
try{if(complete)r=solve_equilibrium(m,problem);else{auto c=compile_problem(m,problem);if(y[7]==0){for(int k=0;k<2;k++){std::vector<double>xp{x[2*k],x[2*k+1]};for(int j=0;j<2;j++)y[(k?4:0)+j]=std::log(xp[j]);y[k?6:3]=std::log(m.packing_fraction_coefficient(t,xp)*rho[k]);}y[2]=1;y[7]=p;auto d=m.evaluate(t,1/rho[0],{x[0],x[1]},DerivativeOrder::IsothermalPhaseHessian);for(int j=0;j<2;j++)y[8+j]=std::log(x[j]*rho[0])+d.gradient[2+j];}EquilibriumResult structural;structural.model_identity=&m;structural.declaration=std::make_shared<EquilibriumProblem>(c.problem);structural.rows=c.rows;structural.phase_count=2;core::Scope scope("frozen_endpoint");
structural.success=true; const auto at=c.prepare(y,false);
structural.residuals=c.evaluate_at(at).values;structural.classified_residuals=c.classified_residuals(at,structural.residuals);
structural.convergence.residual=maximum_abs(structural.classified_residuals);
structural.requested_tolerance_met=structural.convergence.residual<=problem.solver_options.value(policy::row);
r=publish_candidate(c,at,std::move(structural),scope);
r=refine_selected_endpoint(c,std::move(r),scope);}
if(argc>3) for(const auto& e:capture.trace().events) if(e.name==std::string("polish_step")||e.name==std::string("polish_stop")) {std::cerr<<e.name<<" "<<e.reason<<" ";for(double v:e.values)std::cerr<<v<<",";std::cerr<<"\n";} if(!r.success) std::cerr<<set<<" "<<row<<" "<<arm<<" "<<complete<<" "<<r.message<<"\n";std::cout<<set<<','<<row<<','<<arm<<','<<complete<<','<<r.success<<','<<t<<','<<r.pressure.value_or(NAN);for(int k=0;k<2;k++)std::cout<<','<<(r.molar_densities.empty()?NAN:r.molar_densities[k]);for(int k=0;k<4;k++)std::cout<<','<<(r.mole_fractions.empty()?NAN:r.mole_fractions[k]);std::cout<<','<<(r.linear_solve_diagnostics?r.linear_solve_diagnostics->precision_bits:53)<<','<<(r.linear_solve_diagnostics?r.linear_solve_diagnostics->refinement_iterations:0)<<','<<r.evaluations<<','<<r.iterations<<','<<r.hessian_calls;
if(r.numerical_estimates)std::cout<<','<<r.numerical_estimates->densities[0].chart<<','<<r.numerical_estimates->densities[1].chart<<','<<r.numerical_estimates->pressure.absolute<<','<<r.numerical_estimates->cause;else std::cout<<",nan,nan,nan,";std::cout<<','<<std::count_if(capture.trace().events.begin(),capture.trace().events.end(),[](const auto& event){return std::string_view(event.name)=="mixture_precision_activate";});std::size_t decisions=0;double decision=NAN;for(const auto& e:capture.trace().events) {const std::string_view name(e.name);if(name!="mixture_precision_decision" && name!="mixture_precision_activate")continue;if(name=="mixture_precision_decision"){++decisions;decision=e.values.at(1);}events<<set<<','<<row<<','<<arm<<','<<name;for(size_t i=0;i<4;i++)events<<','<<(i<e.values.size()?e.values[i]:NAN);events<<','<<std::quoted(e.reason)<<'\n';}std::cout<<','<<decisions<<','<<decision;for(const auto* rows:{&r.residuals,&r.classified_residuals}){double max=0;for(double v:*rows)max=std::max(max,std::abs(v));std::cout<<','<<max;}std::cout<<','<<r.requested_tolerance_met.value_or(false)<<','<<problem.solver_options.value(policy::row)<<'\n';}
catch(const std::exception&e){std::cerr<<set<<' '<<row<<' '<<arm<<' '<<complete<<' '<<e.what()<<'\n';return 1;}
}}}
